import{_ as t,a as o,b as a}from"./chunks/export-result.B4wpZCeU.js";import{_ as r,o as n,c as s,a2 as i}from"./chunks/framework.Dx-TCpNt.js";const f=JSON.parse('{"title":"Export","description":"Export turns a chapter of panels and notes into something you can actually carry: an HTML study document, PNG images for slides, a .docx for people who…","frontmatter":{"description":"Export turns a chapter of panels and notes into something you can actually carry: an HTML study document, PNG images for slides, a .docx for people who…"},"headers":[],"relativePath":"guide/export.md","filePath":"guide/export.md","lastUpdated":1794780892000}'),d={name:"guide/export.md"};function l(h,e,g,p,c,u){return n(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h1><p>Export turns a chapter of panels and notes into something you can actually carry: an HTML study document, PNG images for slides, a <code>.docx</code> for people who live in Word, or a print view for the PDF crowd.</p><figure class="shot"><img src="'+t+'" alt="Export dialog with layout templates, scope, languages, image mode and a live preview"><figcaption>The export dialog. The left column configures the document; the right side previews the layout and can be resized by dragging the divider.</figcaption></figure><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Your notes live inside the app, glued to panels. Reviewing them on a tablet, printing them, or dropping a comparison into a slide deck all need a portable artifact that keeps the page image and the matching notes together — without uploading anything.</p><h2 id="opening-the-dialog" tabindex="-1">Opening the dialog <a class="header-anchor" href="#opening-the-dialog" aria-label="Permalink to &quot;Opening the dialog&quot;">​</a></h2><p>Press <code>E</code>, or click <strong>Export</strong> in the top bar. The dialog always exports the page or chapter you are looking at.</p><h2 id="html-export" tabindex="-1">HTML export <a class="header-anchor" href="#html-export" aria-label="Permalink to &quot;HTML export&quot;">​</a></h2><h3 id="title-and-scope" tabindex="-1">Title and scope <a class="header-anchor" href="#title-and-scope" aria-label="Permalink to &quot;Title and scope&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Document title, also used for the suggested file name.</td></tr><tr><td><strong>Current page</strong></td><td>Exports only the open page.</td></tr><tr><td><strong>Whole chapter (n pages)</strong></td><td>Exports every annotated page in the chapter.</td></tr><tr><td><strong>Only pages with notes</strong></td><td>Skips pages without notes; useful for a study-notes collection.</td></tr><tr><td><strong>Languages</strong></td><td>Which languages appear in the document.</td></tr></tbody></table><h3 id="image-mode" tabindex="-1">Image mode <a class="header-anchor" href="#image-mode" aria-label="Permalink to &quot;Image mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th></tr></thead><tbody><tr><td><strong>Sibling <code>.files</code> folder</strong> (default)</td><td>The HTML references images in a folder next to it. Smaller and faster to load. Copy both together.</td></tr><tr><td><strong>Bundle into a single file</strong></td><td>Images are inlined as data URLs. One file to share, but a full chapter can be tens of megabytes.</td></tr></tbody></table><p><strong>Draw panel borders on the original image</strong> overlays the panel rectangles on the exported artwork. This is independent of annotations.</p><p><strong>Only export notes with these tags</strong> filters notes by tag; <strong>Clear filters</strong> removes the selection.</p><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><p>Three built-in layout templates:</p><table tabindex="0"><thead><tr><th>Template</th><th>Result</th></tr></thead><tbody><tr><td><strong>Image left, notes right</strong></td><td>Manga page on the left, page and panel notes on the right.</td></tr><tr><td><strong>Image top, notes below</strong></td><td>The image spans the full width and notes unfold underneath.</td></tr><tr><td><strong>Panel comparison</strong></td><td>Each panel shows several languages side by side with its notes.</td></tr></tbody></table><p>Layout templates can be saved under a custom name, exported as JSON and imported again. They live in <code>data/templates/export.json</code>. The layout controls are:</p><table tabindex="0"><thead><tr><th>Control</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Image column width</strong></td><td>Width of the image column, in percent.</td></tr><tr><td><strong>Column gap</strong></td><td>Space between image and notes.</td></tr><tr><td><strong>Font size</strong></td><td>Base font scale for the document.</td></tr><tr><td><strong>Columns per row</strong></td><td>Number of page blocks per row.</td></tr></tbody></table><p>The layout is remembered automatically. You can also drag the divider in the live preview to set the image width.</p><h3 id="generating" tabindex="-1">Generating <a class="header-anchor" href="#generating" aria-label="Permalink to &quot;Generating&quot;">​</a></h3><ol><li>Choose scope, languages, image mode and layout.</li><li>Click <strong>Generate HTML</strong>.</li><li>When it finishes, the dialog reports how many pages were exported and where the file went.</li><li>Use <strong>Open HTML</strong> to open it in the browser, or <strong>Download HTML</strong> to save a copy. With the default image mode, copy the <code>.files</code> folder as well.</li></ol><p>Files are written to the project&#39;s <code>exports/</code> folder. The HTML opens directly from disk.</p><h3 id="printing" tabindex="-1">Printing <a class="header-anchor" href="#printing" aria-label="Permalink to &quot;Printing&quot;">​</a></h3><p>The generated HTML includes print styles: backgrounds are removed, the page width is unconstrained, and page blocks avoid breaking mid-image. Open the file in a browser and use the normal <strong>Print</strong> command to produce a PDF via the browser&#39;s print dialog.</p><div class="tip custom-block"><p class="custom-block-title">Printing to PDF</p><p>Choose <strong>PDF (print)</strong> in the export dialog — the print view opens with the browser print dialog, where you pick <strong>Save as PDF</strong>. See <a href="#pdf-and-word">PDF and Word</a>.</p></div><h2 id="png-export" tabindex="-1">PNG export <a class="header-anchor" href="#png-export" aria-label="Permalink to &quot;PNG export&quot;">​</a></h2><p>The <strong>Export PNG</strong> section produces images directly, without a document:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Content</th></tr></thead><tbody><tr><td><strong>Whole page</strong></td><td>The page image with panel borders and annotations.</td></tr><tr><td><strong>Current panel</strong></td><td>The selected panel, cropped and aligned.</td></tr><tr><td><strong>Trilingual collage</strong></td><td>The selected languages placed side by side for the same panel (or the whole page when no panel is selected).</td></tr></tbody></table><p>Options:</p><ul><li><strong>Include annotations (n)</strong> — draws the annotation layer into the PNG. The count shows how many marks will be included.</li><li>Whole-page and current-panel PNG use the <strong>primary (base) language</strong>; the collage uses the selected compare languages.</li><li><strong>Current panel</strong> is disabled until a panel is selected in the workbench.</li></ul><p>PNGs are generated in the browser and land in the browser&#39;s download folder. They paste straight into slides, documents or chat.</p><figure class="shot"><img src="'+o+'" alt="Export dialog with the scope, language chips, image mode, PNG modes and layout sliders"><figcaption>The export dialog with the PNG modes visible. Whole page and current panel use the primary language; the trilingual collage uses the selected languages.</figcaption></figure><h2 id="pdf-and-word" tabindex="-1">PDF and Word <a class="header-anchor" href="#pdf-and-word" aria-label="Permalink to &quot;PDF and Word&quot;">​</a></h2><p>The export dialog has three output formats: <strong>HTML</strong>, <strong>Word document</strong> and <strong>PDF (print)</strong>.</p><h3 id="word-docx" tabindex="-1">Word (<code>.docx</code>) <a class="header-anchor" href="#word-docx" aria-label="Permalink to &quot;Word (`.docx`)&quot;">​</a></h3><ol><li>Press <code>E</code> and choose <strong>Word document</strong>.</li><li>Set the scope, languages and note tag filter as usual.</li><li>Click <strong>Generate Word</strong>, then <strong>Download .docx</strong>.</li></ol><p>The document keeps the page images and turns page and panel notes into editable Word text. Annotations are <strong>not</strong> embedded in the <code>.docx</code> yet — use a PNG or the HTML export when you need the marks.</p><h3 id="pdf-print" tabindex="-1">PDF (print) <a class="header-anchor" href="#pdf-print" aria-label="Permalink to &quot;PDF (print)&quot;">​</a></h3><ol><li>Choose <strong>PDF (print)</strong> and click <strong>Generate print view</strong>.</li><li>The print view opens in a new tab and brings up the browser print dialog.</li><li>Choose <strong>Save as PDF</strong>.</li></ol><p>Images are fitted to one page and notes stay with their page. Backgrounds are removed, the page width is unconstrained and page blocks avoid breaking mid-image.</p><h3 id="plain-text-markdown" tabindex="-1">Plain text / Markdown <a class="header-anchor" href="#plain-text-markdown" aria-label="Permalink to &quot;Plain text / Markdown&quot;">​</a></h3><p>Use <strong>Copy page context</strong> or the <strong>Rendered / Source</strong> toggle on a note; the note body is Markdown.</p><h2 id="export-templates" tabindex="-1">Export templates <a class="header-anchor" href="#export-templates" aria-label="Permalink to &quot;Export templates&quot;">​</a></h2><p>An export template (<code>.mnexp</code>) stores the layout and style settings so the same look can be reused or shared. Export and import templates through <strong>Exchange files…</strong> in the sidebar. Imported templates are validated and the original file is backed up under <code>data/backups/exchange/</code>.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>The HTML has broken images.</strong> With the default mode, the <code>.files</code> folder must travel with the HTML. Move them together.</li><li><strong>A single-file export is enormous.</strong> That is expected: every image is inlined. Use the <code>.files</code> mode for a whole chapter.</li><li><strong>A page is missing from the export.</strong> It has no notes and <strong>Only pages with notes</strong> is on, or it has no images in the selected languages.</li><li><strong>Panel borders are not in the PNG.</strong> PNG export uses the annotation toggle; enable <strong>Include annotations</strong>, and remember that panel borders are drawn from the panel rectangles, not from annotations.</li><li><strong>Print output is cropped.</strong> Set the browser print scale to “Fit to page” and enable background graphics only if you need the shading.</li><li><strong>Word ignored the layout.</strong> Paste the rendered HTML rather than the Markdown source; Word keeps HTML tables and images but not the two-column drag width.</li><li><strong>The <code>.docx</code> or PDF button is missing.</strong> Both are in the export dialog: choose <strong>Word document</strong> or <strong>PDF (print)</strong> at the top. Annotations are not embedded in Word yet.</li><li><strong>The output folder is not writable.</strong> In a packaged desktop build, <code>exports/</code> lives inside the chosen library folder.</li></ul><figure class="shot"><img src="'+a+'" alt="Exported HTML opened in a browser: manga pages on the left and page and panel notes on the right"><figcaption>The exported HTML opened in a browser: manga on the left, page and panel notes on the right.</figcaption></figure><h2 id="missing-screenshots" tabindex="-1">Missing screenshots <a class="header-anchor" href="#missing-screenshots" aria-label="Permalink to &quot;Missing screenshots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>Needed for</th></tr></thead><tbody><tr><td>PNG mode comparison</td><td>Whole page / panel / collage</td></tr><tr><td>export template controls</td><td>Save, import and apply</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/notes">Notes</a> — what ends up in the document.</li><li><a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a> — exporting the whole project instead.</li><li><a href="/KomaYomi-docs/guide/shortcuts">Keyboard Shortcuts</a> — <code>E</code> opens this dialog.</li></ul>',52)])])}const x=r(d,[["render",l]]);export{f as __pageData,x as default};
